def _load_embedded_module(module_name: str, payload: str):
    module = _types.ModuleType(module_name)
    module.__file__ = str(Path(__file__).resolve()) + f'::<{module_name}>'
    module.__package__ = ''
    sys.modules[module_name] = module
    source = _zlib.decompress(_base64.b85decode(payload.encode('ascii')))
    exec(compile(source, module.__file__, 'exec'), module.__dict__)
    return module
_load_embedded_module('das_qc', _DAS_QC_CORE_B85)
_paper_module = _load_embedded_module('das_qc_paper', _DAS_QC_PAPER_B85)

def build_config() -> dict:
    return {'acquisition': {'sample_rate_hz': SAMPLE_RATE_HZ, 'spatial_interval_m': SPATIAL_INTERVAL_M, 'expected_channels': EXPECTED_CHANNELS, 'expected_duration_seconds': EXPECTED_FILE_DURATION_S, 'duration_tolerance_seconds': DURATION_TOLERANCE_S}, 'hdf5': {'data_dataset': H5_DATASET_PATH, 'channel_axis': CHANNEL_AXIS, 'channel_numbers_are_one_based': DATA_CHANNEL_NUMBERS_ARE_ONE_BASED}, 'layout': {'sheet_name': LAYOUT_SHEET, 'source_channel_offset': SOURCE_CHANNEL_OFFSET, 'coordinate_unit': 'cm', 'unlisted_channels_role': 'leadin'}, 'processing': {'block_seconds': READ_BLOCK_SECONDS, 'boundary_seconds': BOUNDARY_CHECK_SECONDS}, 'thresholds': {'max_nonfinite_fraction': MAX_NONFINITE_FRACTION, 'max_zero_fraction': MAX_ZERO_FRACTION, 'max_saturation_fraction': MAX_SATURATION_FRACTION, 'max_flat_fraction': MAX_FLAT_FRACTION, 'std_group_robust_z': STD_GROUP_ROBUST_Z, 'min_soft_qc_group_size': MIN_SOFT_QC_GROUP_SIZE, 'max_kurtosis': MAX_PEARSON_KURTOSIS, 'max_jump_std_ratio': MAX_JUMP_DIVIDED_BY_STD, 'fixed_bad_min_file_fraction': FIXED_BAD_MIN_FILE_FRACTION, 'saturation_values': FLOAT_SATURATION_VALUES}, 'plots': {'representative_channels': REPRESENTATIVE_CHANNELS, 'raw_start_second': RAW_WAVEFORM_START_S, 'raw_duration_seconds': RAW_WAVEFORM_DURATION_S, 'heatmap_bin_seconds': HEATMAP_BIN_SECONDS}, 'paper_figures': {'representative_files': REPRESENTATIVE_FILES, 'auto_representative_count': AUTO_REPRESENTATIVE_FILE_COUNT, 'dpi': PAPER_FIGURE_DPI}}

def require_path(path_text: str | None, label: str, allow_empty_file: bool=False) -> Path | None:
    if path_text is None:
        return None
    path = Path(path_text)
    if not path.exists():
        raise FileNotFoundError(f'{label}不存在：{path}')
    if path.is_file() and (not allow_empty_file) and (path.stat().st_size == 0):
        raise ValueError(f'{label}为空：{path}')
    return path

def main() -> int:
    layout = require_path(LAYOUT_XLSX, '布设表')
    data_dir = require_path(H5_INPUT_DIR, 'H5输入目录')
    file_info = require_path(FILE_INFO_CSV, '文件信息表', allow_empty_file=True) if FILE_INFO_CSV else None
    if data_dir is not None and (not data_dir.is_dir()):
        raise NotADirectoryError(f'H5_INPUT_DIR必须是目录：{data_dir}')
    output = Path(RESULT_OUTPUT_DIR)
    output.mkdir(parents=True, exist_ok=True)
    config_path = output / '本次质控参数.json'
    config_path.write_text(json.dumps(build_config(), ensure_ascii=False, indent=2), encoding='utf-8')
    arguments = ['run', '--input', str(data_dir), '--output', str(output), '--config', str(config_path), '--layout', str(layout)]
    if file_info is not None:
        arguments += ['--file-info', str(file_info)]
    if RECURSIVE:
        arguments.append('--recursive')
    print('=' * 72)
    print('DAS数据质量检查（单文件版）')
    print(f'布设表：{layout}')
    print(f'H5输入：{data_dir}')
    print(f'输出目录：{output}')
    print(f"文件信息表：{(file_info if file_info else '未提供')}")
    print(f'参数快照：{config_path}')
    print('=' * 72)
    return _paper_module.main(arguments)
if __name__ == '__main__':
    try:
        raise SystemExit(main())
    except (FileNotFoundError, NotADirectoryError, ValueError) as error:
        print(f'参数错误：{error}', file=sys.stderr)
        print('请修改本文件最上方的“用户参数区”后重新运行。', file=sys.stderr)
        raise SystemExit(2)
